# owner: platform
import unittest

from rosterkit.models import Student
from rosterkit.contacts import ContactError, contact_rows

def student(number, last, first, section, email):
    return Student(number, last, first, section, email)

class ContactRowTests(unittest.TestCase):
    def test_rows_are_sorted_and_aligned(self):
        rows = contact_rows([
            student("2", "Young", "Al", "B", "al@x.org"),
            student("1", "Adams", "Beth", "AA", "b@x.org")
        ])
        self.assertEqual(rows, [
            "Adams, Beth  AA  b@x.org",
            "Young, Al    B   al@x.org"
        ])

    def test_missing_email_names_the_student(self):
        with self.assertRaises(ContactError) as ctx:
            contact_rows([
                student("1", "Adams", "Beth", "A", None)
            ])
        self.assertIn("Adams, Beth", str(ctx.exception))

    def test_blank_email_is_missing(self):
        with self.assertRaises(ContactError):
            contact_rows([
                student("1", "Adams", "Beth", "A", "")
            ])

    def test_empty_list_raises(self):
        with self.assertRaises(ContactError):
            contact_rows([])

if __name__ == "__main__":
    unittest.main()
